import{_ as s,o as e,c as p,a3 as r}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"1.5智能最大毛产","description":"","frontmatter":{"translationSource":{"title":"1\\\\.5智能最大毛产","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=umMgUzRULECbKVLsX5rOlZ","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-5-automatic-maximum-gross-production"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/1-5-automatic-maximum-gross-production"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-5-automatic-maximum-gross-production"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/1-5-automatic-maximum-gross-production"}]]},"headers":[],"relativePath":"zh/1-5-automatic-maximum-gross-production.md","filePath":"zh/page-umMgUzRULECbKVLsX5rOlZ.md"}'),i={name:"zh/1-5-automatic-maximum-gross-production.md"};function o(c,a,l,n,d,t){return e(),p("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><h1 id="_1-5智能最大毛产" tabindex="-1">1.5智能最大毛产 <a class="header-anchor" href="#_1-5智能最大毛产" aria-label="Permalink to &quot;1\\.5智能最大毛产&quot;">​</a></h1><blockquote><p>源页面 ID：<code>umMgUzRULECbKVLsX5rOlZ</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=umMgUzRULECbKVLsX5rOlZ" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>视频链接<br> 产线本体：<a href="https://www.bilibili.com/video/BV1tgbW6RE6W/?share_source=copy_web&amp;vd_source=9f60c330d7b703cb7375642cd8db2daf" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1tgbW6RE6W/?share_source=copy_web&amp;vd_source=9f60c330d7b703cb7375642cd8db2daf</a><br> 自适应讲解：<br> 自动配平讲解：</p><p><a href="https://zmdjj.pythonanywhere.com/" target="_blank" rel="noreferrer">群友做的本页面阅读网站</a>，答疑人员可以引用其内部，防止腾讯文档有时抽风，导致全跳转到《终末地物流bug导论》那个子页面的问题出现。</p><p><span id="source-block-M4g2iTuaxVbrNLXFtNtyLJ"></span></p><h2 id="_1-5智能最大毛产出基建蓝图" tabindex="-1">1.5智能最大毛产出基建蓝图 <a class="header-anchor" href="#_1-5智能最大毛产出基建蓝图" aria-label="Permalink to &quot;1.5智能最大毛产出基建蓝图&quot;">​</a></h2><p><span class="mark-red"><u><strong>常见问题自查</strong></u></span><span class="mark-red"><strong>请往下翻，拓展功能使用请往下翻<br> 若因为问出</strong></span><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-yDRC0KVhKSyTDPUKCagyWK">1.5智能最大毛产</a><span class="mark-red"><strong>中能直接解决的问题，很可能被忽略提问</strong></span></p><p><span class="mark-red"><strong>如果有任何其他需求，请询问腾讯文档ai阅读或先看一遍目录（电脑端目录在左侧，手机端目录需要在文档右上角手动呼出）再向群友提问</strong></span></p><p><span id="source-block-bmoqVFuDdN4lBYeIp0H6bn"></span></p><h3 id="蓝图更新记录" tabindex="-1">蓝图更新记录 <a class="header-anchor" href="#蓝图更新记录" aria-label="Permalink to &quot;蓝图更新记录&quot;">​</a></h3><ul><li><p>2026.9.7 13:49 更新蓝图：武陵05</p></li><li><p><span class="mark-grey"><s>2026.9.8 00:26 更新蓝图：应龙关01、应龙关03（无效更新）</s></span></p></li><li><p>2026.9.15 2:56 更新蓝图：应龙关（全部）</p></li><li><p>2026.9.16 0:57 更新蓝图：景玉谷（全部）</p></li><li><p>2026.9.21 更新蓝图：龙泡泡二阶段</p></li></ul><p>更新后蓝图可查阅下方对应区域的蓝图码，更新详情见<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-kK6NOYj9oOxPhfdKLYWdO5">1.5智能最大毛产</a></p><p><span id="source-block-GPl9UvYR9IrVP89xMoefeT"></span></p><h3 id="蓝图准备工作-拍蓝图前请务必阅读" tabindex="-1"><strong>蓝图准备工作（拍蓝图前请务必阅读）</strong> <a class="header-anchor" href="#蓝图准备工作-拍蓝图前请务必阅读" aria-label="Permalink to &quot;**蓝图准备工作（拍蓝图前请务必阅读）**&quot;">​</a></h3><p><strong>请确认仓储情况：</strong></p><p><span class="mark-red"><u><strong>10000+息壤 10000+赤铜块 500+锦草 500+芽针 500+砂叶种子</strong></u></span><span class="mark-red"><strong></strong></span><span class="mark-red">2000+赤铜零件 1000+紫晶零件 1000+铁制零件 1000+晶体外壳 1000+源矿</span><span class="mark-grey">（没下划线的用来做设备，如果设备足够可以不准备）</span><span class="mark-red"><br></span>且<span class="mark-red"><strong>灼铜块未满仓</strong></span></p><p><em>P.S. 用于制造设备时，谷地和武陵仓储互通。</em></p><p><strong>请确认基地升级：</strong></p><p>需要<span class="mark-red">升满所有的区域扩大和存取线基段</span>（实际上首墩和应龙关的存取线可以少点两级），必须<span class="mark-red">开启除了炮台之外</span><span class="mark-red"><u>所有科技点</u></span>（部分科技点<span class="mark-red">存在前置任务</span>，请自行完成查漏补缺）</p><p><strong>请确认禁区</strong><span class="mark-red"><strong>息壤气矿</strong></span><strong>：</strong></p><p>需要<span class="mark-red">80+息壤气/min（等效4个高纯矿点以上）的息壤气</span>输送到应龙的盈天台基地<span class="mark-grey">（常见问题汇总底部有禁区息壤气连接示意图）</span></p><p><strong>此外，拍蓝图时需要注意：</strong></p><ul><li><p>在拍下一张蓝图之前，务必<span class="mark-red">完成上一张蓝图设备的布置（完成设备制作与提交，不能是黄色待建造状态）</span></p></li><li><p>请不要在蓝图的产线里擅自做任何视频演示以外的修改<span class="mark-grey">（包括但不限于：修改准入口限速，修改/重放/删除管道件和物流件，修改管道/暗管连接，拿取产线内部的息壤气/液化息壤/锦草溶液/芽针溶液）（如果想修改可以在群聊或者b站评论区询问）</span></p></li></ul><p>如果库存赤铜零件不足，可考虑使用以下蓝图：</p><p>《明日方舟：终末地》蓝图 [赤铜零件准备]分享码EF012UOAUUI4O8UAeIOo 请复制后前往游戏中使用。</p><p><span class="mark-grey">此蓝图需要接入两个水泵，可生产120/min的赤铜零件。（注意不要断电哦~）</span></p><p><span id="source-block-aZli93Lno95jxDGgn1OJj9"></span></p><h3 id="应龙-自动赫灼18灼" tabindex="-1">应龙-自动赫灼18灼 <a class="header-anchor" href="#应龙-自动赫灼18灼" aria-label="Permalink to &quot;应龙-自动赫灼18灼&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6c42221152df9dc3.q90-c93ab1aa4e5d85b5.webp" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="HCnByLGH77mPDjMIfChk33"><p>盈天台布局示意</p></div><p>《明日方舟：终末地》蓝图 [应龙断电池]分享码EF01ao68oo706A06oe5e 请复制后前往游戏中使用。<br><span class="mark-blue">制备好反应池后（即反应池中有清水、源矿、蓝铁矿、赤铜矿、赤铜零件各一），将此反应池移动到空地并删除剩余结构，放好应龙01后，用制备好的反应池替代01中的断电反应池。</span></p><p>《明日方舟：终末地》蓝图 [应龙01]分享码EF0193au33A6ae1a5UI2 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [应龙02]分享码EF01u284221I80IOAoOU 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [应龙03]分享码EF01081388U91i4uE179 请复制后前往游戏中使用。</p><p><span class="mark-blue">放完应龙关蓝图之后，连接好各处暗管，可参考下图。</span><span class="mark-grey">（2x3+1个酸泵，1个水泵，1个惰气矿机）</span></p><p>重大更新记录：<span class="mark-red">2026.9.15 2:56重置整个应龙基地以修复自动赫灼bug</span></p><p>若已安装原有蓝图，请遵循以下方式修改：</p><ul><li><p>根据视频连接暗管过程，逐个将连接外部的暗管挪出基地，然后删除原有应龙基地。</p></li><li><p>删除原有应龙基地时请<span class="mark-red">不要保留</span>断电反应池，请<span class="mark-red">重新进行断电池制备</span>。</p></li><li><p>重拍前请确保有500+息壤库存且赫铜块灼铜块均未满仓，如果没有息壤库存请根据<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a>进行操作，如果赫铜块灼铜块满仓就消耗500+赫铜零件和灼铜零件。</p></li><li><p>新版的暗管和断电反应池与它们在旧版中的位置基本一致。</p></li><li><p>重拍可参考<a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">【终末地1.5】【谨慎抄取】集成援助龙泡泡补丁！一次毕业两期！_哔哩哔哩bilibili</a></p></li></ul><p><span class="mark-grey"><em>为什么强调单口连多口？这是因为多口连多口允许2-4/s的液气输送，而“多口暗管-管道汇流器”的优先级结构是让流量大于2/s的部分进入次优先的管道，这使得优先级不完全。举个例子，某多口连多口的实时流量是“1/s持续1s 2/s持续1s 3/s持续1s”，那么平均流量是2/s，理应没有任何物品进入“多口暗管-管道汇流器”的优先级结构中的次优先的管道，但实际上在“3/s持续1s”中是持续1s的2/s进入优先的管道而1/s进入次优先的管道，次优先的管道意外进入了1/3/s的物品！而单口多口相连就直接将流速限制在2/s，使得该优先级结构为完全的优先级。</em></span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4e286bc5922f1d90.q90-f49b6c0492282133.webp" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="JNhEYLWV8BPJfbMON08kn0"><p>外接暗管示意</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ebaa20e4ccef4279.jpeg" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="A59zrlSbK9s4cFFlW2Expe"><p>内接暗管示意</p></div><p><span id="source-block-twa6LIcdMfCj7nW2vtdGKB"></span></p><h3 id="武陵-7池6液气兼容中电爆仓稳态" tabindex="-1">武陵-7池6液气兼容中电爆仓稳态 <a class="header-anchor" href="#武陵-7池6液气兼容中电爆仓稳态" aria-label="Permalink to &quot;武陵-7池6液气兼容中电爆仓稳态&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-72bd09479c37b968.jpeg" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="MYpVHU0ktpJmZHAzwGwOgt"><p>武陵主基地布局示意</p></div><p>《明日方舟：终末地》蓝图 [武陵01]分享码EF0170i9002Ui521O0Ai 请复制后前往游戏中使用。</p><p><span class="mark-blue">放完01后，根据准入口设置所有协议核心取货口为赤铜块。</span></p><p>《明日方舟：终末地》蓝图 [武陵02]分享码EF014AEiAAo5E34OE71A 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [武陵03]分享码EF01E75U77u25o8o3uIa 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [武陵04]分享码EF01081388U91ieIE179 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [武陵05]分享码EF016u0Iuui1078uOa3e 请复制后前往游戏中使用。<span class="mark-red">2026.9.7 13:49更新本蓝图（05），更新详情请移步下方更新日志，无需重拍蓝图。</span></p><p>《明日方舟：终末地》蓝图 [武陵06]分享码EF01A671665i7EAu91eO 请复制后前往游戏中使用。</p><p><span class="mark-blue">若有连接净水节点或应龙-武陵息壤气，则参考下图连接暗管；若没有连接净水节点，则不要忘记自己补上污水处理，根据不同情形可选用以下两个蓝图之一。</span></p><p>《明日方舟：终末地》蓝图 [净水暗管连接]分享码EF01u28U5Ie8701AoOU 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [不使用净水节点]分享码EF01u28U5Ie870oAoOU 请复制后前往游戏中使用。</p><p><span class="mark-blue">放完武陵城蓝图之后，连接14个水泵和4个惰气泵，确保都有物品流入</span><span class="mark-grey">（管道接到准入口侧面.jpg)</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1e4e6161266364ef.q90-fcc78a4d33db5f2e.webp" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="tA3SI8z5lJz2RMMlhvDzVp"><p>外接暗管示意</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a3dc4152d91d1c49.jpeg" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="UKtzFhiBrzaV50a8MBnUCs"><p>内接暗管示意</p></div><p><span id="source-block-qMT4GtWsR8rDPnonIh5VLq"></span></p><h3 id="景玉-12息壤2中电" tabindex="-1">景玉-12息壤2中电 <a class="header-anchor" href="#景玉-12息壤2中电" aria-label="Permalink to &quot;景玉-12息壤2中电&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-585d88628da76e7b.jpeg" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="gwzITkvDHIWivEN6dCB2FZ"><p>天王坪布局示意</p></div><p>《明日方舟：终末地》蓝图 [景玉01]分享码EF018OIEOO93I18uUI73 请复制后前往游戏中使用。</p><p><span class="mark-blue">放完01后，根据准入口设置协议核心取货口。(不要连接取货口与准入口之间的传送带，02蓝图会帮你连)</span></p><p>《明日方舟：终末地》蓝图 [景玉02]分享码EF01081388U91i6IE179 请复制后前往游戏中使用。(<span class="mark-red">2026.9.16 11:28前惰气散布机前准入口未限速</span>，若在此之前复制蓝图就自己改一下或者直接重拍）</p><p><span class="mark-blue">放完02后连接惰气+清水，每个清水准入口连接一水泵，惰气准入口连接一气矿或更多。一共需要9个水泵，不要使用分流器</span></p><p>重大更新记录：<span class="mark-red">2026.9.15 2:56重置整个景玉谷基地。（现在的蓝图和视频中的不一样，新的摆放教程在</span><a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">【终末地1.5】【谨慎抄取】集成援助龙泡泡补丁！一次毕业两期！_哔哩哔哩bilibili</a><span class="mark-red">）</span></p><p><span class="mark-grey">新基地大幅降低各种息壤失压发生的可能性，其实就是将息壤部分原本的存入口入库改成了箱子入库，让取货口大体上轮询以保证加压正常。另外换成了明管进水/惰气，降低了抄错的可能性。</span></p><p>若已安装原有蓝图，可遵循以下方式修改：</p><p><span class="mark-grey">（如果基建报表正确、未出现异常状况，可以不进行修改）</span></p><ul><li><p>将单口暗管出口的水和惰气挪到基地边上备用，然后删除原有景玉谷基地。</p></li><li><p>移除原有的多口暗管，清水和惰气将改为明管连接。</p></li><li><p>重拍前请确保锦草和砂叶种子有500+的库存，以及1000+的息壤库存，防止重拍时壤晶线缺乏息壤而发生损坏。若息壤库存已耗尽则移步<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a>。由于需要拆除息壤产线并重造，可能会出现息壤需求严重不足的情况，可以在重拍完景玉谷后，根据<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a>修复位于主基地的壤晶线。</p></li><li><p>重拍可参考<a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">【终末地1.5】【谨慎抄取】集成援助龙泡泡补丁！一次毕业两期！_哔哩哔哩bilibili</a></p></li></ul><p><span id="source-block-bV0Hdv0wVPjL7qIf7R1aEm"></span></p><h3 id="首墩-虽然很小-但是必放" tabindex="-1">首墩（虽然很小，但是必放） <a class="header-anchor" href="#首墩-虽然很小-但是必放" aria-label="Permalink to &quot;首墩（虽然很小，但是必放）&quot;">​</a></h3><p>《明日方舟：终末地》蓝图 [赤铜零件准备]分享码EF012UOAUUI4O8UAeIOo 请复制后前往游戏中使用。</p><p><span class="mark-grey">放置蓝图前/放置蓝图时发现赤铜零件不够可以用。</span></p><p>以下两张蓝图任选其一即可，每个清水准入口连接一水泵，惰气准入口连接二气矿或更多：</p><p>《明日方舟：终末地》蓝图 [首墩 有箱]分享码EF01eaA0aaE7A412o9i8 请复制后前往游戏中使用。</p><p><span class="mark-grey">体积稍小，多用了箱子的电。</span></p><p>《明日方舟：终末地》蓝图 [首墩 无箱]分享码EF013Eo74uioeau90579 请复制后前往游戏中使用。</p><p><span class="mark-grey">体积稍大，少用了箱子的电。</span></p><p><span id="source-block-0sNX0wBVHLjwM9Rp2FzvjJ"></span></p><h3 id="龙泡泡插件-已经结束的活动-无需抄取" tabindex="-1">龙泡泡插件（已经结束<span class="mark-grey"><u><strong>的活动，无需抄取）</strong></u></span> <a class="header-anchor" href="#龙泡泡插件-已经结束的活动-无需抄取" aria-label="Permalink to &quot;龙泡泡插件（已经结束&lt;span class=&quot;mark-grey&quot;&gt;&lt;u&gt;**的活动，无需抄取）**&lt;/u&gt;&lt;/span&gt;&quot;">​</a></h3><p><span id="source-block-md1ZBjonVneH9c7Z1UVSH4"></span></p><h4 id="一阶段-主基地-首墩-6-min息壤龙泡泡" tabindex="-1">一阶段-主基地/首墩-6/min息壤龙泡泡 <a class="header-anchor" href="#一阶段-主基地-首墩-6-min息壤龙泡泡" aria-label="Permalink to &quot;一阶段-主基地/首墩-6/min息壤龙泡泡&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d998b8c45e664f7a.q90-0228a8a7d382f57e.webp" alt="15智能最大毛产"></p><p>安装可参考<a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">【终末地1.5】【谨慎抄取】集成援助龙泡泡补丁！一次毕业两期！_哔哩哔哩bilibili</a></p><p>放在主基地空地或者首墩空地都行。</p><p><span class="mark-red">考虑到赤铜块压力可能不足，请根据</span><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a><span class="mark-red">中的指示关闭三台粉碎机（或者你希望赤铜块有积累以完全避免压力不足则可以考虑关闭更多，事实上这就是</span><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-6rcRwbuFHgJ50Hq0nLJmk8">1.5智能最大毛产</a><span class="mark-red">中的内容）。考虑到息壤压力不足导致壤晶线损坏请根据</span><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a><span class="mark-red">中的指示关闭四台反应池。</span></p><p>《明日方舟：终末地》蓝图 [一阶段01]分享码 请复制后前往游戏中使用。</p><p><span class="mark-blue">已经过实战检验，系正常运行。</span></p><p><span id="source-block-Sp48AHGvwvLIbjxO4OoUeX"></span></p><h4 id="二阶段-首墩-7-5-min重息壤龙泡" tabindex="-1">二阶段-首墩-7.5/min重息壤龙泡 <a class="header-anchor" href="#二阶段-首墩-7-5-min重息壤龙泡" aria-label="Permalink to &quot;二阶段-首墩-7.5/min重息壤龙泡&quot;">​</a></h4><p>最近更新时间：9月21日</p><p><span class="mark-blue">已经过实战检验，系正常运行。</span></p><p><span class="mark-red"><strong>！！！鉴于不少人一阶段都不能保证产出正常，而二阶段的原料调用比一阶段更多对原有产线负荷更重，如果在使用二阶段蓝图前仍没有解决问题的能力很可能无法换完活动商店的5w折金券，现在换成别的蓝图还来得及，请对自己的账号负责！！！</strong></span></p><p><strong>但是话又说回来了，不管这毛毛雨的5w折金券的话其实6/min重息壤龙泡泡0/min息壤龙泡泡也够用换了，总之自己看着办吧。</strong></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fca454156743051e.jpeg" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="6nWq8O4SS6a5FIpYCcBK0c"><p>二阶段布局示意图</p></div><p><span class="mark-grey"><em>二阶段没开，配方都没解锁，开之前抄这个当然不会有产出了！抄了又不想拆就关关掉吧，会偷吃36/min的息壤。二阶段解锁是9月22号。</em></span></p><p>安装可参考<a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">【终末地1.5】【谨慎抄取】集成援助龙泡泡补丁！一次毕业两期！_哔哩哔哩bilibili</a></p><p>因为需要整合惰气，所以需要重拍首墩，重拍前请将连好的惰气暗管移出基地。也就是说为什么不能作为插件直接拍的原因是惰气不够用了。</p><p>同样的，由于惰气不足，二阶段龙泡泡产能难以进一步提升，需要保留主基地6/min的一阶段龙泡泡产线以换完活动商店。<strong>但是只要不管商店里的毛毛雨一样的5w折金券的话其实6/min重息壤龙泡泡0/min息壤龙泡泡也够用换了，所以并不是一定要保留一阶段产线，如此一来失压情况也没有下面说得这么严峻。（2026.9.23 4:26 补充了这一段加粗白字）</strong></p><p><span class="mark-red">考虑到赤铜块压力可能不足，请根据</span><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a><span class="mark-red">中的指示关闭</span><span class="mark-red"><u><strong>六台</strong></u></span><span class="mark-red">粉碎机</span><span class="mark-red"><strong>（息壤空仓而铜块未空仓则关闭八台）</strong></span><span class="mark-red">（或者你希望赤铜块有积累以完全避免压力不足则可以考虑关闭更多，事实上这就是</span><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-6rcRwbuFHgJ50Hq0nLJmk8">1.5智能最大毛产</a><span class="mark-red">中的内容）。考虑到息壤压力不足将导致壤晶线损坏请根据</span><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a><span class="mark-red">中的指示关闭</span><span class="mark-red"><u><strong>四台</strong></u></span><span class="mark-red">反应池。</span></p><p><span class="mark-red"><strong>如果仍然发生壤晶线息壤失压则将景玉谷更换为9月15号更新的版本，如果已更换则关掉更多赤铜粉碎机。更极端更保险的办法参考</strong></span><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-b0yB7GcYPo8AVeFqRmsf5g">1.5智能最大毛产</a></p><p><span class="mark-blue"><strong>以及仅限于龙泡泡活动可以考虑采用的关闭一台主基地的重息壤固气机。</strong></span></p><p><span class="mark-grey">不过如果重息壤已爆仓的话那基本上不可能发生息壤失压了。</span></p><p>《明日方舟：终末地》蓝图 [二阶段01]分享码 请复制后前往游戏中使用。9月21日修正配方后更新。</p><p><span class="mark-grey">紧贴西南角放置，按准入口标签接好水和酸和惰气，注意水和酸一管对一泵 惰气则是一管对二矿。然后等待反应池开始产生息壤液后再拍02 。</span></p><p>《明日方舟：终末地》蓝图 [二阶段02]分享码 请复制后前往游戏中使用。9月21日修正配方后更新。</p><p><span class="mark-grey">嵌入01放置。</span></p><p><span class="mark-blue">蓝图维护小贴士：可能的故障来自于从东往西数第二台液气机，因为它混息壤和铜，一般来说拍完01等待充分即01有息壤液产生后拍02则完全不会故障，但是如果因为种种原因真的发生故障可以自行掏这台液气的原料槽中卡住的1铜液。</span></p><p><span class="mark-red">一般来说需要一定时间暖机，如果拍下产线并解锁配方，10分钟后还未生产，说明有问题。</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a8a378d4c7edcd5c.q90-8bae6ab08a2f6d95.webp" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="RhOnMNAyQ5GBt8tFkFC4Dx"><p>7.5/min重息壤龙泡泡 6/min息壤龙泡泡（1）</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-149d1ec1ed2b9c52.q90-25d7473d97238e3a.webp" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="Y79xkNd4LbcYqzKvTnwxGL"><p>7.5/min重息壤龙泡泡 6/min息壤龙泡泡（2）</p></div><p><span id="source-block-Uv3fH2ncTMOWEtYds9hNwm"></span></p><h4 id="停止灼铜-赫铜生产-进阶内容" tabindex="-1">停止灼铜/赫铜生产（进阶内容） <a class="header-anchor" href="#停止灼铜-赫铜生产-进阶内容" aria-label="Permalink to &quot;停止灼铜/赫铜生产（进阶内容）&quot;">​</a></h4><p>此时可以大量添加龙泡泡产线取代灼铜/赫铜的原料使用，而不是视频<a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">【终末地1.5】【谨慎抄取】集成援助龙泡泡补丁！一次毕业两期！_哔哩哔哩bilibili</a>中所演示的仅开6/min一阶段产线或着7.5/min二阶段产线。</p><p><span class="mark-blue"><strong>下图忘了说，关掉应龙之后主基地和首墩还是会继续打粉，得把那些打粉也关了不然要傻等铜粉满仓</strong></span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-f7d725a9d4a73fbb.q90-b3f500f1a9fdcd9f.webp" alt="15智能最大毛产"></p><p>（光看下图别忘了主基地还有一条小泡泡）此时我们让龙泡泡成为铜末端，应该供满息壤和重息壤，让龙泡泡产线吃完重息壤没用光的铜，也就是加压息壤和重息壤，不加压铜（重息壤是二阶配方要用到，因为有库存所以直接给出正常数量的取货口就算加压了）。<strong>其实把铜的取货口删一半让一口对一个配件机即可：</strong></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e7793617068a6faf.q90-9c45a18d6e67943c.webp" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="ENiQjtYcE8Ti6vYhThPTJZ"><p>一点没压缩哈哈</p></div><p>如果需要的话自取蓝图码**（建议分离芯/壤晶满仓再用这个，不然少摆一条）**：<br> 《明日方舟：终末地》蓝图 [息壤龙泡泡！？]分享码 请复制后前往游戏中使用。</p><p><span class="mark-red">另外有个比较猎奇的事情是最终配平效果是14.75中电2.3125小药26.758重息壤22.155息壤龙泡泡，息壤龙泡泡换成券已经超过老乡总产券了（2215.5&gt;2036）...可以考虑关一条然后重息壤加速并且有一定铜积累。</span></p><p><span class="mark-grey">作者用下来感觉还是关掉一条（作者关的是主基地那条）比较好一点，不然息壤失压不好修，而且除了加速了爆仓别的也没啥区别啊我感觉（）而且yj这什么设计，龙泡泡没券也能硬换但是不想硬换还得自己注意别把券换完（）</span></p><p><span class="mark-grey">感觉多做龙泡泡真是错了的，灼赫爆仓了我还能做炮台，龙泡泡换券然后重息壤爆仓了我还能做啥啊（（</span></p><p><span id="source-block-XjBQl3qROfHLoRb49jWuJy"></span></p><h4 id="全自动切换阶段" tabindex="-1">全自动切换阶段 <a class="header-anchor" href="#全自动切换阶段" aria-label="Permalink to &quot;全自动切换阶段&quot;">​</a></h4><p><span class="mark-grey">新建文件夹中，请耐心等待后续更新……</span></p><p><span id="source-block-yDRC0KVhKSyTDPUKCagyWK"></span></p><h2 id="常见问题汇总" tabindex="-1">常见问题汇总： <a class="header-anchor" href="#常见问题汇总" aria-label="Permalink to &quot;常见问题汇总：&quot;">​</a></h2><p><span class="mark-red">大部分问题可以通过重新拍产线解决（更精细的做法可参考下文“暖机相关部分”）</span></p><p><span class="mark-red"><strong>！！！不要在上一张的蓝图设备尚未制作完成（黄色待建造状态）就拍下一张蓝图，请先完成设备制作并提交，否则将导致优先级损坏！！！</strong></span></p><p><span class="mark-red"><strong>！！！不要在蓝图的产线里擅自做任何视频演示以外的修改！！！</strong></span></p><p><span class="mark-grey"><strong>（包括但不限于：修改准入口限速，修改/重放/删除管道件和物流件，修改管道/暗管连接，拿取产线内部的息壤气/液化息壤/锦草溶液/芽针溶液）（如果想修改可以在群聊或者b站评论区询问）</strong></span></p><p><span class="mark-blue">向群聊内或者b站评论投放产能报表寻求答疑时，请一律展示以下物品（可在报表中点击星标置顶物品方便展示）：<br> 源矿 蓝铁矿 赤铜矿 赤铜块 蓝铁粉末 赤铜粉末 致密源石粉末 赫铜块 息壤 重息壤 壤晶 灼铜块 分离芯 赤铜溶液 气态赤铜 气态赫铜 气态灼铜 中容武陵电池（默认排序 升序）</span></p><p><span class="mark-blue"><strong>若不遵守我们很可能忽略您的提问。</strong></span></p><ol><li><p><u>景玉谷蓝图不能放下去</u>：请仔细观看新的视频带摆<a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">【终末地1.5】【谨慎抄取】集成援助龙泡泡补丁！一次毕业两期！_哔哩哔哩bilibili</a>；检查是否手动连接了协议核心与准入口之间的传送带；检查基地内是否有掉落物（罕见）</p></li><li><p><u>若应龙关管道物流上限</u>：酸液暗管改用多口暗管，不使用管道汇流器，惰气矿同理；检查是否在基质刷取点放置了大量管道件限位。</p></li><li><p><u>产物报表有波动</u>：是正常的，因为自适应产线有大量震荡的运行以自动控制反应速率，不要大惊小怪；机器时开时停是正常的，这是自适应震荡供料，避免所有息壤浪费，所以我们才有这么高的产量，装置细节可以移步：<a href="/endfield-skydoc/zh/some-simpler-adaptive-setups">较简单的自适应装置们</a></p></li><li><p>息壤、蓝铁块、赤铜块、致密源石粉末消耗大于产出是正常的。<span class="mark-grey">事实上，从息壤/赤铜块仍有库存直到产线抵达最终稳态（即息壤/赤铜块空仓而分离芯/壤晶满仓）产线实际给出是“这段时间的息壤/赤铜块总产量+息壤/赤铜块在一开始的库存量”的最优灼铜重息壤的配比，</span><span class="mark-grey"><u>换而言之，只要没有全部爆仓，暖机完毕的产线事实上一直处于完全体。</u></span></p></li><li><p><u>息壤库存为零，但是需要息壤</u>：因为上一条提到息壤消耗大于产出，也就是在任意产物爆仓前息壤最终会归零，那么有没有什么办法留一点息壤呢？请移步下文的“暖机相关”部分<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a></p></li><li><p><u>发电量不超过9800/大断电且赤铜块满仓</u>：解耦模块出现问题，大概率是拍蓝图时仓库中没有500+锦草，请准备好足量锦草<span class="mark-grey">（40+）</span>后重拍主基地蓝图，或者参考这个视频修复<a href="https://www.bilibili.com/video/BV1btnA6VE9R/" target="_blank" rel="noreferrer">垃圾桶修复参考</a>。</p></li><li><p><u>灼铜块产量在60/min左右</u>：很大可能是赫铜块没有满仓，我们设计的自动赫灼切换会在赫铜块未满仓时1:2地生产赫铜和灼铜。是正常的，灼铜和重息壤和电池可以轻松换完券。<span class="mark-grey">实在不要赫铜可以关闭断电反应池边上的赫铜气准入口，关闭方式是开启限制通过数量为1。</span></p></li><li><p><u>赫铜块、灼铜块产速降低严重</u>（对半砍甚至更多，当然没那么多其实也有可能是这一条）：检查北部禁区息壤气多口暗管出口的上游（即与该多口暗管出口相连暗管入口处），若为多口暗管入口则必须只使用一个口，保持另一个口不流入息壤气，只在一个口汇流息壤气（或者将这个多口暗管入口改为单口暗管入口）。<u><strong>另一种可能是</strong></u>息壤气气矿没接够80——一个高纯气矿是20一个低纯气矿是10，不要接少了<span class="mark-grey">（北部禁区息壤气多口暗管连接的储气罐中没有息壤气大概率是这个问题）</span>。<u><strong>还有一种可能是</strong></u>扩容反应池的息壤输入失压，重拍蓝图或者请移步下文的“暖机相关”部分<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a></p></li><li><p><u>息壤产量未达到360</u>：检查景玉谷植物（即锦草）是否放置足够、水泵连接是否无误，惰气的连接是否正常（惰气矿处易受高低差影响未接入暗管），如果把暗管移动至其他地方进行连接，请记得把连接好的暗管和多口暗管放回它们在基地内原本的位置。<span class="mark-grey">检查水管连接情况：上方8个入水口，每个入水口连接一个水泵，基地外拉一条单口暗管，连接一水泵放在侧边，一共9个水泵。</span><span class="mark-red">如果是锦草不足则大概率后续会发生常见问题6，请前往排查</span><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production">1.5智能最大毛产</a></p></li><li><p>应龙关部分暖机较慢，这是正常的（大概需要1-2h）。若想加速请移步下文的“暖机相关”部分<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a></p></li><li><p>灼铜爆仓较长时间（半小时以上）后卖出灼铜时，此时应龙关不会立即开始生产，而是需要花费10-20分钟自动解除自锁，无灼铜产出系正常现象，不要大惊小怪。</p></li><li><p><u>赤铜块在未满仓的情况下产量只有</u><u><strong>390</strong></u>：请检查接往净水节点/废水处理机的单口暗管和多口暗管是否接反。类似的，若开满矿机而<u>赤铜块产量不足510</u>，都应该尝试检查污水疏通和清水供应是否正常，或者矿点供水是否正常。</p></li><li><p><u>赫铜未满仓但无赫铜相关产出</u>：检查应龙关协议核心附近的反应池的朝向是否正确；检查协议核心的方向是否正确；检查断电反应池是否正确制备。</p></li><li><p>多检查水泵酸泵是否正确连接，以及武陵主基地内的暗管连接是否正确，尤其是壤晶产量不为81（使用净水节点）或75（不使用净水节点）时请检查污水相关的暗管连接是否正确（注意检查净水节点暗管连接是否和视频介绍一致）。</p></li><li><p><u>壤晶产量为0</u>：请先检查息壤产量，0息壤产量会导致壤晶不生产，排查方法详见9；排除问题9后，请检查水泵连接（河边最角落有一个水入口，请不要遗漏）。也可能为解耦模块出现问题，排查方法见6</p></li><li><p><u>壤晶产量为0-31</u>：若电池爆仓则为正常情况；若电池未爆仓则请检查主基地壤晶线，维修办法见下文的“暖机相关”部分。</p></li><li><p><u>分离芯未达到产出大于消耗</u>：在息壤产速达到360、赤铜块产速510的前提下（未达到请排查问题9、12），检查分离芯产线上游的息壤和赤铜块取货口中是否有一直不运输物品的，如果有请重新放置取货口；检查惰气矿连接是否正常，惰气矿可能因高低差原因未接上。</p></li><li><p><u>赤铜粉末充足的情况下赤铜粉末消耗未达到360</u>：若灼铜块满仓则为正常情况；在排除问题8的情况下，请检查连接赤铜液生产线的酸液暗管（即应龙关基地角落的三个摆放在一起的运输酸液的暗管）是否因高低差漏接或与另一个单酸泵暗管接错，这三个暗管全都是需要接入两个酸泵的，请逐一排查。<span class="mark-grey">赤铜粉末消耗速度为300时则高度怀疑为酸泵漏接或接错，如遇到该情况，请务必注意。</span></p></li><li><p><strong>武陵主基地中惰气入口侧的液气转化机不在正常工作是正常的</strong>，其只会在下游缺少息壤气且上游液化息壤足够的情况下自动启动，不用理会即可，相信产线智能。</p></li><li><p>关于<u>售卖物品</u>：该蓝图推荐售卖灼铜零件，中容武陵电池，重息壤，芽针针剂<span class="mark-grey">（蓝色的）</span>。不推荐售卖赫铜零件，不能售卖分离芯或息壤。如果希望提高产出，可以关闭武陵城主基地协议核心附近的灼铜装备原件机。更进一步的，可以参考<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production">1.5智能最大毛产</a></p></li><li><p><u>不产出优质芽针针剂</u>：蓝图没有产出，并且从换券角度来说灼铜零件是更优的。当然如果是自己要吃，可以在空地拿赤铜块手搓。具体可以拿取什么，拿取多少可以参考下文的自由调用部分。<span class="mark-grey">（不要拿产线内部的芽针/锦草溶液）</span></p></li></ol><p><span class="mark-grey">恭喜您看到了这里，您已经超过了80%的群友了(≧∇≦)/ </span><span class="mark-grey"><s>（没这么少）</s></span></p><p>若想了解进一步的原理可以移步：</p><ul><li><p>装置的自适应/自动控制激活物/激活物零浪费<a href="/endfield-skydoc/zh/some-simpler-adaptive-setups">较简单的自适应装置们</a></p></li><li><p>自动配平<a href="/endfield-skydoc/zh/explanation-automatically-balanced-production-lines-and-adaptive-devices#source-block-JHB9yrgA7h2xtO0t0QlxBz">讲解：自配平产线和自适应装置</a>（仅为视频脚本）</p></li></ul><p><span class="mark-blue">产线无息壤浪费运作前提：应龙关的盈天台输入80/min以上的息壤气，300/min（10洪炉）以上息壤产出，280/min以上赤铜矿产出（并不需要拉满矿点和地区建设等级）</span></p><p><span class="mark-blue">净水节点接入与否/超库存传输致密源石粉末与否/源矿矿点拉满与否均不影响产线不浪费息壤地完成自动配平，但是需要注意至少要能产够发电用的电池</span></p><p>P.S. 如果<u><strong>能</strong></u>达到18灼件（12灼件6赫件）36重15电池基本上就对了，<strong>不过这并不代表其他报表情形就不对。</strong><span class="mark-grey">事实上只要产线正确，基于不同的原料和中间产物的情况会有不一样的报表，而它们也都是正确的。</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-137aed48cee7f36b.q90-aca6a5ee9222b010.webp" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="UbHqZ9L6agWgXK5qnHRKI1"><p>应龙关息壤气相关-连接参考</p></div><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-330335c1b50a1621.q90-afaeee960e8ec8ac.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-3c1a67bbd1fedb8c.q90-899dc838aff2d2a0.webp" alt="图片"></td></tr></tbody></table><p><span class="mark-grey">左侧需要跑图，省一对暗管；右侧能直接传送，多一对暗管</span></p><p>另外，如果连了祀的画的息壤气则可以：</p><p>北部禁区南部40气<span class="mark-grey">（2个气矿）</span>和雪松林50气<span class="mark-grey">（全部气矿）</span>汇流到<span class="mark-red">单口暗管入口（绝对不可以多口）</span>后连应龙关基地内的多口暗管出口、北部禁区北部60气<span class="mark-grey">（2+1个气矿）</span>和祀的画40气在北部禁区北部汇流后连原雪松林在应龙基地的单口暗管出口。</p><p><span class="mark-grey">怎么看气矿有多少气？高纯矿点20气，低纯矿点10气，暗管可传输120气。</span></p><p>以上全部看不懂，就把祀的画的40气一路拉到应龙关基地和雪松林50气暗管出口汇流。</p><p><span id="source-block-sdvd1X3RJrhAL32oIkexUc"></span></p><h2 id="暖机相关" tabindex="-1">暖机相关 <a class="header-anchor" href="#暖机相关" aria-label="Permalink to &quot;暖机相关&quot;">​</a></h2><p>请在有一定息壤库存时启动本蓝图<br> 那如果没有那怎么办呢</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-788d46ce6b993357.q90-3274c78a48a959d2.webp" alt="15智能最大毛产"></p><p>关上上图的四个池子就能积累了，暖好机别忘了重新打开。<span class="mark-blue">当然如果你希望仓库里积累息壤也可以一直关着，更进一步的利用请移步下文“自由调用”部分。</span><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-4KFSHVD7aAsnzKeVp1Dyo5">1.5智能最大毛产</a><br><strong>类似的，如果应龙关的扩容反应池液化息壤产量不足60/min（即没有满速生产液化息壤）或者生产分离芯的封装机缺少息壤也可以用这个办法重置取货口轮询；类似的，如果生产分离芯的封装机缺少赤铜耐压罐也就是缺少赤铜块，可以关闭主基地东南角的几个粉碎机积累一些赤铜块以重置取货口轮询。</strong></p><p><span class="mark-red">没有息壤会发生什么？小概率的分离芯/壤晶息壤加压不足导致壤晶线损坏和自动配平失效（分离芯失压）。如何修复壤晶线请看下图：</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6a8f7a49d718e711.q90-22e32aacb6cf6d33.webp" alt="15智能最大毛产"></p><p>至于为什么，我只能说神秘yj的神秘取货口/存入口的神秘优先级神秘发力了，我们有尝试探索规律但是几乎无功而返——1.6基建我们一定做以洪炉为起点的固体息壤总线结构（（（</p><p>另外应龙暖机比较慢，因为要填2000液化息壤缓存，别担心，启动慢是正常的。<span class="mark-grey">等我启动.jpg 我已启动.jpg</span></p><p><span class="mark-blue">当然，只要把应龙所有的液化息壤暗管都填满液化息壤，就即刻暖机完成了。</span></p><p><span id="source-block-O9Y1NDa77n2YmO3RXdzq6a"></span></p><h2 id="自动赫灼恶性bug-已解决" tabindex="-1">自动赫灼恶性bug（已解决） <a class="header-anchor" href="#自动赫灼恶性bug-已解决" aria-label="Permalink to &quot;自动赫灼恶性bug（已解决）&quot;">​</a></h2><p>当铜/铜粉未空仓时灼铜/赫铜线会全力生产，也就是说赫铜块输出为30/min，而令人忍俊不禁的是离线状态下赫铜块通过断电反应池和物品准入口会被降速，大概下线8-12h后赫铜块就会堆满机器（在线时不会有问题），如下图所示（可以看到并没有显示停产）</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3d226a234f53ce5c.q90-e710c4b01eb4a878.webp" alt="15智能最大毛产"></p><p>机器中存在50赫铜会使得断电池截断赫铜气时将会流向断电池并在其中积累的赫铜是机器中的50赫铜+管道与机器中残余赫铜气将产出的赫铜，后者是我们设计的小于100赫铜气，产生的赫铜不会填满断电池缓存。但是加上机器中的50赫铜后就会溢出来堵住传送带，使得后续生产的灼铜也无法正常通过，如下图所示：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c2341731e9436b6a.q90-df53e542fc400244.webp" alt="15智能最大毛产"></p><p><span class="mark-blue"><strong>补充——一劳永逸的解决方法：</strong></span><br> 经过b友善意提醒我注意到实际情况中很难避免铜没有积累，重息壤和灼铜随便哪个爆仓之后就积起来了，所以还是要一劳永逸地解决问题，也就是降低赫铜经过反应池和准入口的流量：</p><p><s>通过将多口暗管外置，我们成功取得了修改的空地（大嘘），然后就能让断电池双出双入赫铜块了。真是不优雅的做法啊，但是我们真的没招了。（注：协议箱和多个准入口是不必要的，只是我看这地有位子就塞了，以避免任何可能的问题）</s></p><p><span class="mark-blue"><strong>（2026.9.8）已更新应龙01应龙03蓝图，完全消灭问题。</strong></span><span class="mark-yellow"><strong>（2026.9.10）（由于神秘莫测的离线降速，如果您在正确修改后真的发现赫铜还是把灼铜堵住了，可以向我们反馈样本，简单的修复方法是把固气机里面和传送带上的赫铜掏掉）（搞半天还是准入口降速，yj我真得控制你了，修到现在了！）</strong></span><span class="mark-red"><strong>（2026.9.15 已完全修复，并更新应龙010203蓝图）</strong></span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9522bfa425662ad8.q90-a33446ed3c321797.webp" alt="15智能最大毛产"></p><p>迟滞输出相关理论来自<a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a></p><p><span id="source-block-b0yB7GcYPo8AVeFqRmsf5g"></span></p><h2 id="壤晶线应急修理办法" tabindex="-1">壤晶线应急修理办法 <a class="header-anchor" href="#壤晶线应急修理办法" aria-label="Permalink to &quot;壤晶线应急修理办法&quot;">​</a></h2><p>首先应尝试<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a>中给出的办法并确保自己的景玉谷是9月15号更新的景玉谷<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-qMT4GtWsR8rDPnonIh5VLq">1.5智能最大毛产</a>，若无果请在此基础上使用下面的激进方案</p><p><span id="source-block-WHfdcZtJSaRyhjr8nzKDuf"></span></p><h3 id="小幅降低电池产量" tabindex="-1">小幅降低电池产量 <a class="header-anchor" href="#小幅降低电池产量" aria-label="Permalink to &quot;小幅降低电池产量&quot;">​</a></h3><p><span class="mark-red">需要壤晶已满仓。</span></p><p>减少电池产能以减少壤晶需求量；关闭主基地的电池产线，位置如图：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-337f4c86b1bcc5c7.q90-665d8e059a5ded75.webp" alt="15智能最大毛产"></p><p><span id="source-block-HWIfr9ISfbSyUfbmd7FxEQ"></span></p><h3 id="开启壤晶线自动销毁" tabindex="-1">开启壤晶线自动销毁 <a class="header-anchor" href="#开启壤晶线自动销毁" aria-label="Permalink to &quot;开启壤晶线自动销毁&quot;">​</a></h3><p>代价是壤晶爆仓后将浪费一些原料；需要开启销毁的扩容反应池的位置如图：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-2323ce0c5825a2e4.q90-a178f576f8c0d3f4.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-ae3a1f06ca42a124.q90-6bbd7dc496d4cd36.webp" alt="图片"></td></tr></tbody></table><p><span id="source-block-4KFSHVD7aAsnzKeVp1Dyo5"></span></p><h2 id="自由调用" tabindex="-1">自由调用 <a class="header-anchor" href="#自由调用" aria-label="Permalink to &quot;自由调用&quot;">​</a></h2><p><span id="source-block-J3tMFGGo6XhWKpyc5VQzKj"></span></p><h3 id="自由地新增取货口" tabindex="-1">自由地新增取货口 <a class="header-anchor" href="#自由地新增取货口" aria-label="Permalink to &quot;自由地新增取货口&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-65ca1fd3aabbf9fc.q90-e7a48528efe2258b.webp" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="Ci3HFxaf6g5HPmiJaouB3y"><p>制作另外三种装备原件</p></div><p>直接加就行了（取货口物品选择范围：赤铜块 息壤 重息壤 赫铜块 灼铜块），如果不想考虑太多的话就每种物品不超过两个口。<span class="mark-grey">图中的源矿不要学，或者你和我一样只开一两个口，开多了怕你们玩断电了。蓝铁块的话可以把小药（蓝色品质的芽针针剂）关了开一两个口，多了容易影响壤晶。</span></p><p>那该怎么判断自己有没有加过多呢？见下一小节</p><p><span id="source-block-gej0LiIH7rHaM0Vt2wX0oT"></span></p><h3 id="对已有产线影响" tabindex="-1">对已有产线影响 <a class="header-anchor" href="#对已有产线影响" aria-label="Permalink to &quot;对已有产线影响&quot;">​</a></h3><p>增加取货口太多后壤晶线的息壤供应和分离芯线的息壤/赤铜块供应可能会不足造成不良后果，总之看一下<strong>分离芯和壤晶存量有无下降</strong>，无下降即无问题。</p><p>以下图为例（最终产物均无爆仓，息壤空仓赤铜未空仓）：壤晶产出大于消耗——存量无下降，分离芯产出等于消耗维持满仓——存量无下降，也就是说这位小伙伴的自由调用是没有问题的。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-77d45137a2e671ea.q90-a16e66dcb06a60b3.webp" alt="15智能最大毛产"></p><p>那么如果壤晶/分离芯存量下降，就只能减少取货口数量吗？见下一小节</p><p><span id="source-block-6rcRwbuFHgJ50Hq0nLJmk8"></span></p><h3 id="扩大自由调用区间" tabindex="-1">扩大自由调用区间 <a class="header-anchor" href="#扩大自由调用区间" aria-label="Permalink to &quot;扩大自由调用区间&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b4d2cacf59cf4d37.q90-ac51b31783a3d084.webp" alt="15智能最大毛产"></p><p>关闭后判断自由调用是否过量的方式依然和之前一样，即<strong>确认壤晶/分离芯的存量不下降。</strong></p><p><span id="source-block-yPXXfFf7EL6X4QwKtZP7E6"></span></p><h3 id="加压输入以达到满速。" tabindex="-1">加压输入以达到满速。 <a class="header-anchor" href="#加压输入以达到满速。" aria-label="Permalink to &quot;加压输入以达到满速。&quot;">​</a></h3><p>就是用更多的取货口连上同一条传送带/同一台机器，目的是确保带/机器在空仓下也供料充足。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6a74c5864eabf1f2.q90-f25397b2cd725d46.webp" alt="15智能最大毛产"></p><div class="logistics-image-caption" data-source-block="Rn0gZVH8Z5jubCytBAy9JC"><p>1.5二阶段7.5/min龙泡泡加压示意</p></div><p>需要注意的是，紧贴取货口放置汇流器有优先级现象，在以加压为目的时需要避免。</p><p><span id="source-block-2keVNLDdBAsIkkMmbc6A8b"></span></p><h3 id="_1-5智能最大毛产-1" tabindex="-1"><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production">1.5智能最大毛产</a> <a class="header-anchor" href="#_1-5智能最大毛产-1" aria-label="Permalink to &quot;[1.5智能最大毛产](page-umMgUzRULECbKVLsX5rOlZ.md)&quot;">​</a></h3><p><span id="source-block-yDHClNwcDGibbpxhXKAypZ"></span></p><h3 id="手切三核赫铜模式" tabindex="-1">手切三核赫铜模式 <a class="header-anchor" href="#手切三核赫铜模式" aria-label="Permalink to &quot;手切三核赫铜模式&quot;">​</a></h3><p>首先，找到产线中如图所示的两个暗管出口和准入口</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-03e6aa9080d58e6b.q90-4acd7f671c296549.webp" alt="15智能最大毛产"></p><p>现在对调这两个暗管出口，如图所示</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-636e418498fae49c.q90-d35d20fa6886dd88.webp" alt="15智能最大毛产"></p><p>注意当我们将这些复原后，也就是变回灼铜固化也就是回到第一张图的样子，还需要清理固气机中的剩余赫铜气</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-727b58ca5ab35609.q90-b5cc6cc105ecbd4f.webp" alt="15智能最大毛产"></p><p><span id="source-block-qCgclCgP4EeJ8NQPctqHLi"></span></p><h3 id="全物品" tabindex="-1">全物品！？ <a class="header-anchor" href="#全物品" aria-label="Permalink to &quot;全物品！？&quot;">​</a></h3><p><a href="/endfield-skydoc/zh/1-5-automatic-all-item-production-2">1.5智能全物品</a></p><p><span id="source-block-kK6NOYj9oOxPhfdKLYWdO5"></span></p><h2 id="蓝图更新日志" tabindex="-1">蓝图更新日志 <a class="header-anchor" href="#蓝图更新日志" aria-label="Permalink to &quot;蓝图更新日志&quot;">​</a></h2><p><span id="source-block-SK1GdKSwVckcaqxIeryCmX"></span></p><h3 id="_2026-9-7-13-49" tabindex="-1">2026.9.7 13:49 <a class="header-anchor" href="#_2026-9-7-13-49" aria-label="Permalink to &quot;2026.9.7 13:49&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8d5160886fef8857.q90-927b88c00412452c.webp" alt="15智能最大毛产"></p><p><span id="source-block-eGjXf3am8qXHkuk54zaVaZ"></span></p><h3 id="_2026-9-8-00-26-无效更新" tabindex="-1">2026.9.8 00:26<span class="mark-red">（无效更新）</span> <a class="header-anchor" href="#_2026-9-8-00-26-无效更新" aria-label="Permalink to &quot;2026.9.8 00:26&lt;span class=&quot;mark-red&quot;&gt;（无效更新）&lt;/span&gt;&quot;">​</a></h3><p>失败的对赫灼自动切换的修复，误判了离线降速原因为断电反应池，实际降速原因时是物品准入口。</p><p>因为对离线降速的测试周期十分漫长，更新延误对大家的影响在这里深感抱歉。</p><p><span id="source-block-LFNyZ7wjTCsoYzDyBHqeUv"></span></p><h3 id="_2026-9-15-2-56" tabindex="-1">2026.9.15 2:56 <a class="header-anchor" href="#_2026-9-15-2-56" aria-label="Permalink to &quot;2026.9.15 2:56&quot;">​</a></h3><p>应龙整个基地重置以修复自动赫灼bug，请根据视频连接暗管过程逐个将连接外部的暗管挪出基地，删除原有应龙基地后从断电反应池制备开始重新摆放蓝图。删除原有应龙基地时请不要保留断电反应池，为避免保留方式有误请重新进行断电池制备。蓝图码移步<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-aZli93Lno95jxDGgn1OJj9">1.5智能最大毛产</a><br> 重拍前请确保有500+息壤库存且赫铜块灼铜块均未满仓，如果没有息壤库存请根据<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a>进行操作，如果赫铜块灼铜块满仓就消耗500+赫铜零件和灼铜零件。</p><p><span id="source-block-wb2utUlRz6aEWq0fE41u0Z"></span></p><h3 id="_2026-9-16-0-57" tabindex="-1">2026.9.16 0:57 <a class="header-anchor" href="#_2026-9-16-0-57" aria-label="Permalink to &quot;2026.9.16 0:57&quot;">​</a></h3><p>景玉谷整个基地重置以大幅降低各种息壤失压发生的可能性，其实就是将息壤部分原本的存入口入库改成了箱子入库，让取货口大体上轮询以保证加压正常。另外换成了明管进水/惰气，降低了抄错的可能性。蓝图码移步<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-qMT4GtWsR8rDPnonIh5VLq">1.5智能最大毛产</a></p><p>重拍前请确保锦草和砂叶种子有500+的库存，以及1000+的息壤库存以防重拍时壤晶线缺乏息壤而发生损坏。若息壤库存已耗尽则移步<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a>。实在不想准备息壤库存那就先让壤晶线坏掉，重拍完景玉再根据<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production#source-block-sdvd1X3RJrhAL32oIkexUc">1.5智能最大毛产</a>去修壤晶线，也不是不行。</p><p><span id="source-block-lD4jP6Jb5YIJHyAQt21JkC"></span></p><h3 id="_2026-9-21" tabindex="-1">2026.9.21 <a class="header-anchor" href="#_2026-9-21" aria-label="Permalink to &quot;2026.9.21&quot;">​</a></h3><p>修正了龙泡泡二阶段配方及配比判断错误导致的蓝图问题。</p><p><span id="source-block-PKgviX9HsEAEEJnxfTwyiO"></span></p><h2 id="性能简述" tabindex="-1">性能简述 <a class="header-anchor" href="#性能简述" aria-label="Permalink to &quot;性能简述&quot;">​</a></h2><p>以下产能均为不自行添加其他产线时的情形。</p><p>产能（源矿540/min、蓝铁矿120/min、赤铜矿510/min、息壤气150/min、超库存传输致密源石粉末、连接净水节点、连接应龙关息壤气暗管到主基地）<span class="mark-blue">（赤铜块、息壤均已空仓，壤晶、分离芯均已满仓）</span>（以下数字的单位均为unit/min）：</p><p>赫铜未满仓：34.845(54219/1556)重息壤11.277(17547/1556)灼件5.6385(17547/3112)赫件14.75中电2.3125蓝药0息壤0赤铜矿0源矿0致密源石粉末0蓝铁矿</p><p>赫铜已满仓：28.705(28734/1001)重息壤17.529(17547/1001)灼件0赫件14.75中电2.3125蓝药0息壤0赤铜矿0源矿0致密源石粉末0蓝铁矿（毛产券2836.5 即一天408w武陵券）</p><p>（下列均以赫铜满仓为前提，中电爆仓时按4.5/min消耗中电发电9600）</p><p>中武已满仓：36重息壤16.8灼件0赫件4.5中电3蓝药33.32息壤0赤铜矿360源矿25致密源石粉末37.5蓝铁矿</p><p>灼铜已满仓：36重息壤0灼件0赫件14.75中电2.3125蓝药127.4息壤420赤铜矿0源矿0致密源石粉末0蓝铁矿</p><p>重壤已满仓：0重息壤18灼件0赫件14.75中电2.3125蓝药198.2息壤60赤铜矿0源矿0致密源石粉末0蓝铁矿</p><p>全自动收敛至最优灼铜零件和重息壤配比、赫铜灼铜产出自动切换无需手动清炉灰、自由增加息壤/赤铜块/源矿取货口不影响产线配平剩余原料、接入净水节点与否/地区建设等级满级与否/地图矿点开齐与否/超传致密源石粉末与否都不影响产线配平、某一最终产物爆仓将加速其他产线而无需销毁高价值的最终产物、能够兼容集成援助的龙泡泡</p><p>完全不浪费息壤的稳态：</p><p>①所有产物未满仓②仅赫铜已满仓③仅中武已满仓④全赫模式且赫铜与重息壤未满仓（即可以叠加中武满仓）</p><p>其他稳态存在极低的息壤浪费，当然其实这些所谓的“其他稳态”更容易发生的息壤浪费形式是直接9w息壤爆仓了（从上面的产能拉表就能看出来），所以无需理会</p><p>不改动产线且确保最大电池产出时可支持的最大铜壤调用量：</p><p>83.181息壤 237.10铜矿</p><p>若能改动产线则为510铜矿与251.6息壤（即减去14.75电池用掉的108.4息壤）</p></div>',1)])])}const b=s(i,[["render",o]]);export{u as __pageData,b as default};
